def load_path_content(path, file_type=None):
    if file_type is None:
        file_type = os.path.splitext(path)[1].lstrip('.')

    if file_type == 'json':
        with open(path, 'r') as the_file:
            return json_loads(the_file.read())
    elif file_type in {'yaml', 'yml'}:
        try:
            import yaml
        except ImportError:
            raise ImportError('Pyyaml needs to be installed.') from None
        with open(path, 'r') as the_file:
            return yaml.safe_load(the_file)
    elif file_type == 'toml':
        try:
            import tomli
        except ImportError:
            raise ImportError('Tomli needs to be installed.') from None
        with open(path, 'rb') as the_file:
            return tomli.load(the_file)
    elif file_type == 'pickle':
        with open(path, 'rb') as the_file:
            return pickle_load(file_obj=the_file)
    elif file_type in {'csv', 'tsv'}:
        try:
            import clevercsv
            dict_reader = clevercsv.DictReader
        except ImportError:
            import csv
            dict_reader = csv.DictReader
        with open(path, 'r') as the_file:
            reader = dict_reader(the_file)
            return list(reader)
    else:
        raise UnsupportedFormatErr('Only json, yaml, toml, csv, tsv and pickle are supported.\n'
                                   f' The {file_type} extension is not known.')

def __init__(self, *args, **kwargs):
